#!/usr/bin/env node
/**
 * Gift-guide picks loader (lead 2026-11-18): turns the researched picks in ~/Desktop/Gift-guide-picks/<slug>.json
 * (name, brand, line, href, store, why_trending, louisianaFit) into src/content/giftGuidePicks.ts, the generated file
 * src/content/giftGuideCatalog.ts reads. Usage: node scripts/gift-guide-picks.mjs [<picks dir>]
 *
 * Files starting with "_" are the lead's working files (store lists), not guides, and are not read.
 * A file that breaks any of the page's rules is SKIPPED whole and listed (exit 1 only when no file passes), so
 * nothing reaches the page unchecked:
 *   - every link https and on an allowlisted host (amazon, shopmy, BRAND_SITES, LOUISIANA_SHOPS in giftGuides.ts);
 *   - every Amazon link carries tag=louisianahelpr-20;
 *   - no price anywhere ("$" followed by a digit).
 * The budget guides (under-20 / under-25 / under-50, stocking-stuffers) hold only items the lead checked under the
 * limit (price-verified 2026-11-18). The badges are decided on the page from the brand (giftGuideCatalog.ts), not here.
 */
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const dir = process.argv[2] ?? join(homedir(), "Desktop", "Gift-guide-picks");
const out = new URL("../src/content/giftGuidePicks.ts", import.meta.url);
const content = readFileSync(new URL("../src/content/giftGuides.ts", import.meta.url), "utf8");
const listed = (name) => [...(content.match(new RegExp(`export const ${name} = \\[([^\\]]*)\\]`))?.[1] ?? "").matchAll(/"([^"]+)"/g)].map((m) => m[1]);
const hosts = new Set(["www.amazon.com", "amazon.com", "shopmy.us", ...listed("BRAND_SITES"), ...listed("LOUISIANA_SHOPS"), ...listed("SPONSOR_SITES")]);

/** The 25 Days sponsors guide: every pick there is a sponsor's (lead 2026-11-18: each gets the sponsor badge). */
export const SPONSORS_GUIDE = "25-days-sponsors";
/**
 * Picks left out by the lead, by guide and brand, with the brand kept by name only (lead 2026-11-18: Hilma's probiotic
 * is a health product; the sponsor stays listed by name).
 */
export const NAME_ONLY = [{ guide: SPONSORS_GUIDE, brand: "Hilma" }];
const nameOnly = (slug, p) => NAME_ONLY.some((x) => x.guide === slug && x.brand === p.brand);

const skipped = [];
const guides = {};
for (const file of readdirSync(dir).filter((f) => f.endsWith(".json") && !f.startsWith("_")).sort()) {
  const slug = file.replace(/\.json$/, "");
  const picks = JSON.parse(readFileSync(join(dir, file), "utf8"));
  const errors = [];
  const list = picks.filter((p) => !nameOnly(slug, p)).map((p) => {
    const url = new URL(p.href);
    if (url.protocol !== "https:") errors.push(`${slug}: ${p.href} is not https`);
    if (!hosts.has(url.hostname)) errors.push(`${slug}: ${url.hostname} is not allowlisted (add it to LOUISIANA_SHOPS)`);
    if ((url.hostname === "amazon.com" || url.hostname.endsWith(".amazon.com")) && url.searchParams.get("tag") !== "louisianahelpr-20") errors.push(`${slug}: ${p.href} lacks tag=louisianahelpr-20`);
    for (const v of [p.name, p.line, p.why_trending]) if (/\$\s?\d/.test(v ?? "")) errors.push(`${slug}: price in "${v}"`);
    // Optional flags the research may add later (owner 2026-11-18 badges): copied only when true.
    const flags = Object.fromEntries(["trending", "shipsFast", "localPickup"].filter((k) => p[k] === true).map((k) => [k, true]));
    if (slug === SPONSORS_GUIDE) flags.sponsor = true;
    return { name: p.name, brand: p.brand, line: p.line, href: p.href, ...(p.louisianaFit ? { louisianaFit: true } : {}), ...flags };
  });
  if (errors.length) skipped.push(`${file}: ${[...new Set(errors)].join("; ")}`);
  else guides[slug] = list;
}
if (Object.keys(guides).length === 0) process.exit(1);
if (skipped.length) console.error(`SKIPPED (fix the file or the allowlist, then re-run):\n${skipped.join("\n")}`);
const body = Object.entries(guides).map(([slug, picks]) => `  ${JSON.stringify(slug)}: ${JSON.stringify(picks)},`).join("\n");
writeFileSync(
  out,
  `/** GENERATED by scripts/gift-guide-picks.mjs from ~/Desktop/Gift-guide-picks (researched 2026-11-18). Do not edit; re-run the script. */\n` +
    `export interface ResearchedPick { name: string; brand: string; line: string; href: string; louisianaFit?: true; trending?: true; shipsFast?: true; localPickup?: true; sponsor?: true }\n` +
    `/** Sponsors listed by name only on their guide (their pick is left out). */\n` +
    `export const NAME_ONLY_SPONSORS: Record<string, string[]> = ${JSON.stringify(Object.fromEntries(NAME_ONLY.map((x) => [x.guide, NAME_ONLY.filter((y) => y.guide === x.guide).map((y) => y.brand)])))};\n` +
    `export const RESEARCHED_PICKS: Record<string, ResearchedPick[]> = {\n${body}\n};\n`,
);
console.log(`gift-guide-picks: ${Object.keys(guides).length} guides, ${Object.values(guides).flat().length} picks`);
